using System.Data; using ElectronicsStore.Data; using ElectronicsStore.Models;
namespace ElectronicsStore.Services;
public static class StoreService {
 public static async Task<User> Login(string email,string password){var t=await Db.Query("SELECT c.client_id,c.full_name,c.email,c.password_hash,r.role_name FROM Clients c JOIN Roles r ON r.role_id=c.role_id WHERE c.email=@email AND c.is_active=1",("@email",email.Trim()));if(t.Rows.Count!=1||!Passwords.Verify(password,(string)t.Rows[0]["password_hash"]))throw new InvalidOperationException("Неверный логин или пароль.");var r=t.Rows[0];return new User((int)r["client_id"],(string)r["full_name"],(string)r["role_name"],(string)r["email"]);}
 public static async Task<List<Choice>> Choices(string table){if(table is not ("Categories" or "Manufacturers" or "Suppliers" or "Roles"))throw new ArgumentException("Неизвестный справочник.");var id=table switch{"Categories"=>"category_id","Manufacturers"=>"manufacturer_id","Suppliers"=>"supplier_id",_=>"role_id"};var name=table switch{"Categories"=>"category_name","Manufacturers"=>"manufacturer_name","Suppliers"=>"supplier_name",_=>"role_name"};var t=await Db.Query($"SELECT {id}, {name} FROM {table} ORDER BY {name}");return t.Rows.Cast<DataRow>().Select(r=>new Choice((int)r[0],(string)r[1])).ToList();}
 public static async Task<List<Product>> Catalog(string search,int category,int sort){var order=sort switch{1=>"p.price ASC,p.product_id",2=>"p.price DESC,p.product_id",_=>"p.title,p.product_id"};var t=await Db.Query($"SELECT p.*,c.category_name,m.manufacturer_name,s.supplier_name FROM Products p JOIN Categories c ON c.category_id=p.category_id JOIN Manufacturers m ON m.manufacturer_id=p.manufacturer_id JOIN Suppliers s ON s.supplier_id=p.supplier_id WHERE (@cat=0 OR p.category_id=@cat) AND (CHARINDEX(@q,p.title)>0 OR CHARINDEX(@q,CONVERT(nvarchar(20),p.product_id))>0) ORDER BY {order}",("@q",search.Trim()),("@cat",category));return t.Rows.Cast<DataRow>().Select(r=>new Product((int)r["product_id"],(string)r["title"],(string)r["category_name"],(string)r["manufacturer_name"],(string)r["supplier_name"],(decimal)r["price"],(int)r["stock_quantity"],(int)r["category_id"],(int)r["manufacturer_id"],(int)r["supplier_id"])).ToList();}
 public static Task SaveProduct(int id,string title,int category,int manufacturer,int supplier,decimal price,int stock){Session.RequireManage();if(string.IsNullOrWhiteSpace(title)||title.Length>150||price<=0||price>9999999999.99m||decimal.Round(price,2)!=price||stock<0||category<=0||manufacturer<=0||supplier<=0)throw new ArgumentException("Проверьте название, цену, остаток и справочники.");return Db.Execute(id==0?"INSERT Products(title,category_id,manufacturer_id,supplier_id,price,stock_quantity) VALUES(@t,@c,@m,@s,@p,@q)":"UPDATE Products SET title=@t,category_id=@c,manufacturer_id=@m,supplier_id=@s,price=@p,stock_quantity=@q WHERE product_id=@id",("@t",title.Trim()),("@c",category),("@m",manufacturer),("@s",supplier),("@p",price),("@q",stock),("@id",id));}
 public static Task DeleteProduct(int id){Session.RequireManage();return Db.Execute("DELETE Products WHERE product_id=@id AND NOT EXISTS(SELECT 1 FROM OrderItems WHERE product_id=@id); IF @@ROWCOUNT=0 THROW 50001,N'Товар отсутствует или уже использован в заказе.',1;",("@id",id));}
 public static Task SaveReference(string table,int id,string name,string extra){Session.RequireManage();if(string.IsNullOrWhiteSpace(name)||name.Length>100||extra.Length>200)throw new ArgumentException("Введите название до 100 символов и описание до 200.");var fields=table switch{"Categories"=>("category_id","category_name","description"),"Manufacturers"=>("manufacturer_id","manufacturer_name","country"),"Suppliers"=>("supplier_id","supplier_name","phone"),_=>throw new ArgumentException("Недопустимый справочник.")};var (key,title,details)=fields;return Db.Execute(id==0?$"INSERT {table}({title},{details}) VALUES(@n,@e)":$"UPDATE {table} SET {title}=@n,{details}=@e WHERE {key}=@id",("@id",id),("@n",name.Trim()),("@e",extra.Trim()));}
 public static async Task<DataTable> Users(){Session.RequireAdmin();return await Db.Query("SELECT c.client_id AS Код,c.full_name AS ФИО,c.email AS Логин,r.role_name AS Роль,c.is_active AS Активен FROM Clients c JOIN Roles r ON r.role_id=c.role_id ORDER BY c.client_id");}
 public static Task SaveUser(int id,string name,string email,string phone,int role,string password,bool active){Session.RequireAdmin();if(string.IsNullOrWhiteSpace(name)||name.Length>100||!email.Contains('@')||email.Length>100||phone.Length>20||role<=0)throw new ArgumentException("Проверьте ФИО, почту, телефон и роль.");if(id==Session.Current!.Id)throw new InvalidOperationException("Текущую учетную запись изменять нельзя. Войдите другим администратором.");var hash=id==0||password.Length>0?Passwords.Hash(password):null;return Db.Execute(id==0?"INSERT Clients(role_id,full_name,phone,email,password_hash,is_active) VALUES(@r,@n,@ph,@e,@h,@a)":"UPDATE Clients SET role_id=@r,full_name=@n,phone=@ph,email=@e,password_hash=COALESCE(@h,password_hash),is_active=@a WHERE client_id=@id",("@id",id),("@r",role),("@n",name.Trim()),("@ph",phone),("@e",email.Trim()),("@h",hash),("@a",active));}
}
